python3 -c '
import unicodedata

items = [
    ["㊹", "㊺", "㊻", "㊼"],
    ["﮴", "﮲"],
    ["🃢", "🃣", "🃤", "🃥", "🃦", "🃧", "🃨", "🃩"],
    ["🃧", "🃦"]
]

for i, seq in enumerate(items):
    print(f"Item {i}:")
    for ch in seq:
        print(f"  {ch} U+{ord(ch):04X} {unicodedata.name(ch, \"?\")}")

    # suggest next 5 based on delta of last two
    if len(seq) >= 2:
        d1 = ord(seq[-1]) - ord(seq[-2])
        print(f"  next chars if delta {d1}:")
        for j in range(1, 6):
            try:
                nxt = chr(ord(seq[-1]) + d1 * j)
                print(f"    {nxt} U+{ord(nxt):04X} {unicodedata.name(nxt, \"?\")}")
            except:
                pass
'
